def main():
 audit={r['sheet']:r for b in json.loads((ROOT/'evidence/sheet_report_number_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};dates={r['sheet']:r for b in json.loads((ROOT/'evidence/status_report_date_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};wb=load_workbook(ROOT/SRC,read_only=True,data_only=True);items=[]
 for prefix,cells,anchor,en,fa in EVENTS:
  sheet=f'{prefix}-1 DDR Remark';values={c:wb[sheet][c].value for c in cells};assert all(isinstance(v,str) and v.strip() for v in values.values()),(sheet,values);assert anchor.lower() in ' '.join(values.values()).lower(),(sheet,anchor);num=audit[sheet]['header_report_number'];assert num==prefix
  items.append({'sheet':sheet,'worksheet_prefix':prefix,'header_report_number':num,'header_date_unverified':dates[sheet]['report_date_iso_from_header'],'cells':values,'anchor':anchor,'english':en,'persian':fa})
 wb.close();items.sort(key=lambda x:x['header_report_number']);pg=' '.join(PdfReader(ROOT/PROGRAM).pages[6].extract_text().split());assert '45.9 (Main Plan) + 110.8 (Contingency Plan)' in pg
 c=load_workbook(ROOT/CBS,read_only=True,data_only=True);f=load_workbook(ROOT/CBS,read_only=True,data_only=False);name='Total Cost-EPD & Rigless';refs=['B3','C3','B4','C4','A5','C5'];financial={x:{'cached':c[name][x].value,'formula_or_literal':f[name][x].value} for x in refs};c.close();f.close()
 data={'well':'127WO2','source':SRC,'method':'Selected entries ordered by source header, not signed chronology or a full hourly reconstruction.','events':items,'programme':{'file':PROGRAM,'physical_page':7,'text_excerpt':pg},'cbs':{'file':CBS,'sheet':name,'cells':financial,'caveat':'Cached source ceiling, not recalculated, not approved actual expenditure or proof of rig-less execution.'},'limitations':'Selected entries do not establish all hours, current well status, approved suspension, payments or contractual entitlement.'};(ROOT/'evidence/127wo2_campaign_review.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 for lang in ('EN','FA'):
  fa=lang=='FA';path=ROOT/f'127WO2_Drilling_Engineering_Report_{lang}.docx';d=Document(path);title='بازسازی منتخب تعمیر دوم و تعلیق گزارش‌شده چاه ۱۲۷' if fa else 'Selected AZNS-127 workover 2 and reported suspension reconstruction'
  if any(p.text==title for p in d.paragraphs):continue
  anchor=next(p for p in d.paragraphs if p.text in ('Performance and Parameter Analysis','تحلیل عملکرد و پارامترهای عملیاتی'));h=d.add_heading(title,level=2);h.alignment=1;anchor._p.addprevious(h._p)
  p=d.add_paragraph(f'این {len(items)} مدخل منتخب به ترتیب شماره سرصفحه منبع مرتب شده‌اند؛ ترتیب و تاریخ با سوابق امضاشده تأیید نشده و تمام ساعت‌ها، موانع یا وضعیت کنونی را پوشش نمی‌دهند.' if fa else f'These {len(items)} selected entries are displayed by source header number; order and dates are not validated against signed records, and the selection does not cover every hour, barrier or present condition.');style(p,fa);anchor._p.addprevious(p._p)
  for e in items:
   lead=f"شیت {e['worksheet_prefix']}، شماره سرصفحه {e['header_report_number']} ـ " if fa else f"Worksheet {e['worksheet_prefix']}, header report {e['header_report_number']} — ";cite=f"{SRC}, {e['sheet']}!"+', '.join(e['cells']);p=d.add_paragraph(lead+e['persian' if fa else 'english']+f' [{cite}]');style(p,fa);anchor._p.addprevious(p._p)
  msg=('صفحه ۷ برنامه ۴۵٫۹ روز اصلی + ۱۱۰٫۸ روز احتیاطی را چاپ می‌کند؛ رابطه، دامنه و مرز ارقام با برنامه مصوب باید تطبیق شوند و مدت واقعی نیستند. CBS سقف cache تعمیر/تکمیل/تدارکات ۷٬۶۹۰٬۷۸۳٫۶۱ دلار و تحریک بدون دکل ۸۵۱٬۹۳۳٫۴۴ دلار و جمع ۸٬۵۴۲٬۷۱۷٫۰۵ دلار را نشان می‌دهد. فرمول بازحساب نشده؛ سقف، هزینه واقعی یا اثبات اجرای تحریک نیست. [AZNS-127 Workover #2 Program Rev.03.pdf، صفحه ۷؛ CBS AZNS-127WO2.xlsx، Total Cost-EPD & Rigless!B3:C5؛ evidence/127wo2_campaign_review.json]' if fa else 'Programme p.7 prints 45.9 main + 110.8 contingency days; relationship, scope and boundaries require approved-plan reconciliation and are not actual duration. CBS caches ceilings of USD 7,690,783.61 for re-entry/completion/procurement and USD 851,933.44 for rig-less stimulation, total USD 8,542,717.05. The formula was not recalculated; a ceiling is not actual expenditure or evidence of stimulation execution. [AZNS-127 Workover #2 Program Rev.03.pdf, p.7; CBS AZNS-127WO2.xlsx, Total Cost-EPD & Rigless!B3:C5; evidence/127wo2_campaign_review.json]');p=d.add_paragraph(msg);style(p,fa);anchor._p.addprevious(p._p);d.save(path)
 print('Events',len(items),'cells',sum(len(x['cells']) for x in items))
if __name__=='__main__':main()
